// Construye el body para Gemini con el voice guide de Daniel embebido.
const lead = $('Get New Leads').item.json;

let siteText = '';
try {
  const raw = typeof $json.data === 'string' ? $json.data : JSON.stringify($json.data || '');
  siteText = raw.replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .slice(0, 3000);
} catch (e) { siteText = ''; }

const system = `You draft LinkedIn first-touch DMs for Daniel Zabaleta, founder of Power Flow, an operations automation consultancy. Daniel is a Power Platform and automation specialist with 5 years automating operations at a global fintech (63% productivity gains, systems used at VP level).\n\nVoice rules (non negotiable):\n- Warm, curious, humble. Not pitchy. Direct but human.\n- Under 5 lines total. Short sentences.\n- Pattern: short opener, one SPECIFIC observation about them or their company, honest one-line positioning, ONE real question about their process.\n- Never assume you can help before they confirm the problem. Never promise results.\n- End with a question, always.\n- No em dashes or en dashes anywhere. No emoji. No corporate jargon. No 'I would love to'. No three adjectives in a row.\n- Positioning line to adapt naturally (do not paste verbatim every time): 'I help growing companies eliminate manual operations work.'\n\nOutput ONLY the message text. No preamble, no quotes, no explanations.`;

const userContent = `Prospect:\n- Name: ${lead.name}\n- Role: ${lead.role || 'unknown'}\n- Company: ${lead.company || 'unknown'}\n- Channel: ${lead.channel}\n- Context notes from Daniel: ${lead.context_notes || 'none'}\n- Company website text (may be empty): ${siteText || 'not available'}\n\nWrite the first-touch DM in English.`;

return {
  json: {
    lead_id: lead.id,
    gemini_body: {
      system_instruction: { parts: [{ text: system }] },
      contents: [{ role: 'user', parts: [{ text: userContent }] }],
      generationConfig: { maxOutputTokens: 1024 }
    }
  }
};

const resp = $json;
let draft = '';
try {
  draft = resp.candidates[0].content.parts[0].text.trim();
} catch (e) { draft = ''; }
if (!draft) { draft = 'DRAFT FAILED, revisar ejecución'; }
return { json: { lead_id: $('Build Gemini Body').item.json.lead_id, draft } };
